import{F as e,I as t,R as n,et as r,n as i}from"./chunks/framework.Bs4wm_X5.js";import{Sr as a,br as o,xr as s,yr as c}from"./chunks/assets.BpWoSz4B.js";import{t as l}from"./chunks/AbcRender.tSiVtjqu.js";import{t as u}from"./chunks/ChromaProfile.qWMoDcYG.js";var d=JSON.parse(`{"title":"Fifth and fourth","description":"Perfect, but not equivalent intervals","frontmatter":{"title":"Fifth and fourth","description":"Perfect, but not equivalent intervals","date":"2021-09-07T00:00:00.000Z","cover":"erol-ahmed.jpg"},"headers":[],"relativePath":"theory/intervals/fifth-fourth/index.md","filePath":"theory/intervals/fifth-fourth/index.md","lastUpdated":1790102922000}`),f={name:`theory/intervals/fifth-fourth/index.md`};function p(i,d,f,p,m,h){let g=l,_=u;return r(),e(`div`,null,[d[0]||=t(`<p>Having anchored musical space with the unison and the octave, we meet the intervals that <strong>build structure</strong> on top of it: the perfect fifth and the perfect fourth. These are the architects of harmony — they define keys, drive tension and resolution, and form the backbone of musical movement across cultures. Everything in this article grows from two small integers: <strong>3:2</strong> and <strong>4:3</strong>.</p><table tabindex="0"><thead><tr><th>At a glance</th><th>Perfect fifth (P5)</th><th>Perfect fourth (P4)</th></tr></thead><tbody><tr><td>Just ratio</td><td>3:2</td><td>4:3</td></tr><tr><td>Just size</td><td>701.96 cents</td><td>498.04 cents</td></tr><tr><td>12-TET size</td><td>7 semitones = 700 cents</td><td>5 semitones = 500 cents</td></tr><tr><td>In the harmonic series</td><td>2nd → 3rd harmonic</td><td>3rd → 4th harmonic</td></tr><tr><td>String stop (monochord)</td><td>2⁄3 of the length</td><td>3⁄4 of the length</td></tr><tr><td>Inversion</td><td>becomes a P4</td><td>becomes a P5</td></tr><tr><td>On the 16-grid</td><td>exact line (24/16, +2.0¢)</td><td>floats between lines (21/16, −29.2¢)</td></tr><tr><td>Character</td><td>grounded, open, powerful</td><td>suspended, open, resolving</td></tr></tbody></table><h2 id="fifth-p5" tabindex="-1">Fifth P5 <a class="header-anchor" href="#fifth-p5" aria-label="Permalink to “Fifth P5”">​</a></h2>`,3),n(g,{abc:`[A4e] Ae`}),n(_,{chroma:`100000010000`}),d[1]||=t(`<p>The <strong>second most harmonic interval</strong> (after the octave) is the fifth — <strong>3/2</strong> of any given frequency. If your drone is at 200 Hz, the fifth above sits at 300 Hz. Pythagoras is claimed to be the first to use this law to construct pleasant combinations of musical notes, and the principle is foundational for the modern 12-tone equal temperament.</p><p><strong>Why 3:2 feels &quot;right.&quot;</strong> The harmonics of two notes a fifth apart align constantly: the <strong>third harmonic of the lower note (3f) coincides exactly with the second harmonic of the upper (2 × 1.5f)</strong>, and every second harmonic of the upper keeps landing on every third of the lower. Coiniding harmonics that fall outside the ear&#39;s critical band are precisely what produces sensory consonance (Plomp &amp; Levelt, 1965) — the acoustic root of the fifth&#39;s feeling of strength and correctness.</p><p><strong>The monochord and the cosmos.</strong> Stopping a string at <strong>2⁄3 of its length</strong> sounds a fifth above the open string. Pythagoras read the beauty of 3:2 as evidence of a mathematical harmony underlying the universe — the idea later poetized as the <strong>&quot;music of the spheres.&quot;</strong> His followers revered the <strong>tetractys</strong>, the triangular figure whose rows encode the intervals:</p><ul><li><strong>1</strong> — the monad (unity)</li><li><strong>2</strong> — the dyad (octave, 2:1)</li><li><strong>3</strong> — the triad (fifth, 3:2)</li><li><strong>4</strong> — the tetrad (fourth, 4:3)</li></ul><h3 id="the-fifth-as-a-scale-generator" tabindex="-1">The fifth as a scale generator <a class="header-anchor" href="#the-fifth-as-a-scale-generator" aria-label="Permalink to “The fifth as a scale generator”">​</a></h3><p>Take the lowest starting frequency and go up in two ways:</p><ul><li>multiplying it by <strong>two</strong> — stepping an octave above,</li><li>and multiplying it by <strong>1.5</strong> — stepping a fifth at a time.</li></ul><img src="`+a+`"><p>After <strong>7 octaves and 12 fifths</strong> you&#39;ll end up on the same starting tone — and you&#39;ll find you&#39;ve pressed <strong>all the other tones on the way</strong>. Every new step of a fifth gives a new note: C → G → D → A → E → B → F♯ → C♯ → G♯ → D♯ → A♯ → E♯ → C. (Fourths run the same cycle in reverse: C → F → B♭ → E♭ → A♭ → D♭ → G♭ → B → E → A → D → G → C.) Fold every generated fifth down by octaves — divide by two until it lands in the starting octave — and there you have it: <strong>12 notes in any given octave</strong>. This is why fifths and fourths govern key relationships and modulation: they connect all twelve pitch classes in one systematic loop.</p><img src="`+s+`"><p>This equation shows the approximate equality of <strong>12 perfect fifths and 7 octaves</strong>: (3/2)¹² ≈ 129.74634 versus 2⁷ = 128. If we use the just interval of 3/2, the small leftover difference is the <strong>Pythagorean comma</strong>.</p><p>In musical tuning, the Pythagorean comma (or <strong>ditonic comma</strong>), named after Pythagoras, is the small interval existing in Pythagorean tuning between two enharmonically equivalent notes such as C and B♯, or D♭ and C♯. It is equal to the frequency ratio (1.5)¹⁄2⁷ = 531441⁄524288 ≈ 1.01364, or about <strong>23.46 cents</strong> — roughly a quarter of a semitone (in between 75:74 and 74:73).</p><blockquote><p><strong>Fact:</strong> that 23.46-cent &quot;error&quot; puzzled mathematicians for centuries and spawned the Renaissance <strong>meantone temperaments</strong>, which narrow eleven fifths to ≈696.6 cents to purify the thirds — leaving one howling <strong>wolf fifth</strong> of ≈737.6 cents to be avoided. The comma is the reason temperament exists at all.</p></blockquote><img src="`+o+`"><h3 id="_12-tone-equal-temperament" tabindex="-1">12-Tone Equal Temperament <a class="header-anchor" href="#_12-tone-equal-temperament" aria-label="Permalink to “12-Tone Equal Temperament”">​</a></h3><p>Twelve-tone equal temperament is the musical system that divides the octave into 12 parts, all of which are equally tempered (equally spaced) on a logarithmic scale, with a ratio equal to the 12th root of 2 (¹²√2 ≈ 1.05946). That resulting smallest interval, 1⁄12 the width of an octave, is called a <strong>semitone</strong> or half step.</p><img src="`+c+`"><p>In 12-TET the fifth becomes <strong>700 cents</strong> (1.96 cents narrower than pure 3:2) and the fourth <strong>500 cents</strong> (1.96 cents wider than pure 4:3) — a compromise of about two cents each, small enough that both still sound &quot;perfect.&quot; That tiny narrowing is audible as <strong>slow beating</strong>: at A4–E5 the tempered fifth beats about <strong>1.5 times per second</strong> (the 3rd harmonic of A at 1320 Hz against the 2nd harmonic of E at ≈1318.5 Hz). Piano tuners don&#39;t hide these beats — they <strong>count them</strong>, using specific beating patterns as a ruler for a well-tempered instrument.</p><p><strong>Emotional character.</strong> The perfect fifth feels <strong>stable and grounded, open and spacious</strong> (it defines no major/minor quality), <strong>supportive, and powerful</strong>. Hear it at the openings of Strauss&#39;s <em>Also sprach Zarathustra</em> (the <em>2001</em> theme), the <em>Star Wars</em> main title, or <em>Twinkle, Twinkle, Little Star</em>; on stage it is the guitar <strong>power chord</strong> (root + fifth, usually with octave doubling) and the falling fifth of every V–I cadence.</p><p><strong>Innate?</strong> Infants as young as <strong>2–6 months</strong> prefer consonant intervals over dissonant ones (Zentner &amp; Kagan, 1996; Trainor &amp; Heinmiller, 1998), and 9-month-olds process melodies built on the 3:2 fifth noticeably better than other sequences (Schellenberg &amp; Trehub, 1996) — evidence that fifth-consonance is at least partly hardwired. Yet the Tsimane&#39; of the Bolivian Amazon rate consonance and dissonance as equally pleasant (McDermott et al., 2016), so <em>preference</em> is tuned by culture even where the <em>perception</em> is universal.</p><p><strong>Chromatone view.</strong> On the spectrogram the fifth appears as two colors at a specific, consistent spacing — and walking the circle of fifths cycles you through all 12 colors in a predictable sequence.</p><h2 id="perfect-fourth-p4" tabindex="-1">Perfect fourth P4 <a class="header-anchor" href="#perfect-fourth-p4" aria-label="Permalink to “Perfect fourth P4”">​</a></h2>`,22),n(g,{abc:`[A4d] Ad`}),n(_,{chroma:`100001000000`}),d[2]||=t(`<p>The <strong>perfect fourth is the inverse of the perfect fifth</strong>: ratio <strong>4:3</strong>, about <strong>498.04 cents</strong> in just intonation, five semitones (<strong>500 cents</strong>) in equal temperament. It may be derived from the harmonic series as the interval between the <strong>third and fourth harmonics</strong>. The term <em>perfect</em> identifies it as belonging to the group of perfect intervals (unison, fourth, fifth, octave) — so called because they are neither major nor minor.</p><h3 id="inversion-the-mirror-math" tabindex="-1">Inversion: the mirror math <a class="header-anchor" href="#inversion-the-mirror-math" aria-label="Permalink to “Inversion: the mirror math”">​</a></h3><p>Interval inversion asks: <em>what interval completes the rest of the octave?</em> Fourths and fifths are exact complements:</p><ul><li><strong>Ratios multiply to the octave:</strong> 4/3 × 3/2 = 2/1. In general, the inversion of a ratio R is I(R) = 2/R — so I(3/2) = 4/3 and I(4/3) = 3/2.</li><li><strong>Cents add to the octave:</strong> 498.04 + 701.96 = 1200.00.</li><li><strong>On a string of length L:</strong> stopping at 2⁄3 L sounds the fifth, at 3⁄4 L the fourth; the leftover segments (1⁄3 L, 1⁄4 L) resonate as higher harmonics.</li><li><strong>The gap between them is the whole tone:</strong> 3/2 ÷ 4/3 = <strong>9:8</strong>, the Pythagorean <strong>epogdoon</strong> (203.91 cents; exactly 200 cents in 12-TET). The ancient whole tone was discovered precisely as <em>the space left between a fourth and a fifth</em> — on the keyboard, the step from F up to G.</li></ul><h3 id="the-fourth-s-double-life" tabindex="-1">The fourth&#39;s double life <a class="header-anchor" href="#the-fourth-s-double-life" aria-label="Permalink to “The fourth&#39;s double life”">​</a></h3><p>The perfect fourth is a <strong>sensory consonance</strong> — its harmonics align as cleanly as the fifth&#39;s (the 4th harmonic of the lower note meets the 3rd of the upper). In common-practice harmony, however, it is considered a <strong>stylistic dissonance in certain contexts</strong>: namely in two-voice textures, and whenever it occurs <strong>above the bass</strong> in chords with three or more notes. If the bass note also happens to be the chord&#39;s root, the interval&#39;s upper note almost always temporarily displaces the third of the chord — in popular-music terminology, a <strong>suspended fourth</strong> (sus4), which the ear expects to resolve down to the third.</p><p>Medieval theorists called the fourth above the bass &quot;imperfect&quot; for exactly this reason: its upper note&#39;s harmonic series sits <em>off</em> the bass&#39;s grid, creating a mild mismatch that wants to settle. Its &quot;perfection&quot; as a classification refers to its consonance and mathematical purity, not to its behavior.</p><p><strong>Emotional character.</strong> Where the fifth feels grounded, the fourth feels <strong>suspended, open, resolving, supportive</strong> — a gentle leaning rather than a pillar. Hear it in the opening leaps of <em>Amazing Grace</em>, Wagner&#39;s Bridal Chorus (<em>Here Comes the Bride</em>), and <em>O Tannenbaum</em>: longing and expectation, ready to move on.</p><blockquote><p><strong>Next up:</strong> exactly halfway between the fourth (498¢) and the fifth (702¢) lies the octave&#39;s midpoint at 600 cents — the most notorious interval in Western history, the tritone. Its symmetry, its √2 ratio, and its legend as <em>diabolus in musica</em> get an article of their own; here we only note that P4 and P5 sit as equal-and-opposite mirrors (±101.96 cents) around it.</p></blockquote><h3 id="the-fourth-on-the-16-grid" tabindex="-1">The fourth on the 16-grid <a class="header-anchor" href="#the-fourth-on-the-16-grid" aria-label="Permalink to “The fourth on the 16-grid”">​</a></h3><p>Mapping Chromatone&#39;s linear 16-step fundamental grid (n/16) onto 12-TET pitch classes reveals why the two &quot;perfect&quot; siblings feel physically different:</p><table tabindex="0"><thead><tr><th>Interval</th><th>Grid ratio</th><th>Ratio</th><th>Cents</th><th>Deviation from 12-TET</th></tr></thead><tbody><tr><td>Perfect 5th (P5)</td><td>24/16</td><td>3/2</td><td>702.0</td><td>+2.0</td></tr><tr><td>Perfect 4th (P4)</td><td>21/16</td><td>21:16</td><td>470.8</td><td>−29.2</td></tr></tbody></table><p>The fifth lands on an <strong>exact integer grid line</strong> (24/16 = 3/2) — perfect alignment with the physical frequency-division substrate. The fourth <strong>floats microtonally between grid lines</strong>, which matches its experienced quality: more suspended, less physically grounded.</p><p>In the layered Chromatone model this is coherent architecture, not coincidence:</p><ul><li><strong>Layer 1 — the 3-limit frame</strong> (primes {2, 3}) builds the macro-geometry of pitch space: octave 2:1, fifth 3:2, fourth 4:3, whole tone 9:8 (epogdoon).</li><li><strong>Layer 3 — the 16-grid substrate</strong> is where the fifth aligns exactly and the fourth requires microtonal adjustment.</li></ul><p>Fifths and fourths together form the <strong>geometric skeleton</strong> of pitch space; the fifth is the one member of the family that also locks onto the substrate.</p><h2 id="quartal-and-quintal-harmony" tabindex="-1">Quartal and quintal harmony <a class="header-anchor" href="#quartal-and-quintal-harmony" aria-label="Permalink to “Quartal and quintal harmony”">​</a></h2><p><strong>Quartal harmony</strong> builds harmonic structures from fourths — perfect, augmented, and diminished. A three-note quartal chord on C stacks perfect fourths: <strong>C–F–B♭</strong>. <strong>Quintal harmony</strong> prefers fifths: <strong>C–G–D</strong>.</p><p>Regarding chords built from perfect fourths alone, composer Vincent Persichetti writes:</p><blockquote><p>Chords by perfect fourth are ambiguous in that, like all chords built by equidistant intervals (diminished seventh chords or augmented triads), any member can function as the root. The indifference of this rootless harmony to tonality places the burden of key verification upon the voice with the most active melodic line.</p></blockquote><p>That productive ambiguity made quartal stacking the sound of modal jazz: the famous <strong>&quot;So What&quot; chord</strong> Bill Evans played on Miles Davis&#39;s <em>Kind of Blue</em> is three perfect fourths plus a major third on top (E–A–D–G–B), and McCoy Tyner built whole solos from fourth stacks. The intervals are even built into our instruments: the <strong>guitar is tuned in fourths</strong> (with one third between G and B), while the <strong>violin family is tuned in fifths</strong> (G–D–A–E) — quartal and quintal geography under your fingers. Modern composers extend the idea into <strong>polychords</strong> (stacked fourth/fifth structures combined) and into floating, non-directional <strong>modal harmonies</strong> that replace fifth-based tonality with fourth-based space.</p><h2 id="the-circle-of-fifths-in-practice" tabindex="-1">The circle of fifths in practice <a class="header-anchor" href="#the-circle-of-fifths-in-practice" aria-label="Permalink to “The circle of fifths in practice”">​</a></h2><p>The circle was first drawn in <strong>1679 by Nikolay Diletsky</strong> (Ukrainian theorist and composer) in his <em>Idea grammatiki musikiyskoy</em>, and popularized in the 18th century by Johann David Heinichen (1728) — a diagram of the very cycle generated above by stacking 3:2 steps.</p><p>It is a working map, not decoration:</p><ul><li><strong>Key relationships:</strong> neighboring keys on the circle differ by one accidental and share most notes.</li><li><strong>Chord progressions:</strong> moving around the circle (especially counter-clockwise, i.e., by fourths) creates the strongest harmonic motion — the V–I cadence is just one step of it. Note that a <strong>falling fifth and a rising fourth are the same move</strong>, which is why the circle unifies both intervals.</li><li><strong>Transposition and modulation:</strong> shifting around the circle shows exactly which notes change.</li></ul><p><strong>Chromatone view:</strong> on the spectrogram the circle of fifths appears as a regular pattern of color relationships — cycling through fifths walks you through all 12 colors in order, making the circle intuitive rather than abstract.</p><h2 id="cultural-perspectives" tabindex="-1">Cultural perspectives <a class="header-anchor" href="#cultural-perspectives" aria-label="Permalink to “Cultural perspectives”">​</a></h2><ul><li><strong>Western classical:</strong> the fifth/fourth frame <em>is</em> the harmonic system — circle of fifths, dominant–tonic engine, cadential grammar.</li><li><strong>Indian classical:</strong> the <strong>tanpura</strong> drone sounds <strong>sa and pa</strong> (tonic and fifth) continuously; the sa–pa relationship anchors every raga, while <strong>shrutis</strong> color subtle microtonal variations around these pillars.</li><li><strong>African traditions:</strong> call-and-response patterns and instruments like the <strong>mbira (kalimba)</strong> and marimba emphasize fifths and fourths; pentatonic scales common across the continent naturally outline fifth/fourth relationships.</li><li><strong>Arabic and Persian music:</strong> maqam practice bends and shades fifths and fourths microtonally for melodic expression, keeping the 2:1 octave frame intact.</li><li><strong>Just intonation and experimental music:</strong> pure 3:2 and 4:3 beyond equal temperament, and new microtonal divisions of the fifth and fourth, continue the exploration Pythagoras began.</li></ul><p>Same architecture, different dialects: the 3:2 / 4:3 frame is near-universal; the tuning of its edges is cultural.</p><h2 id="practice-feeling-the-fifth-and-fourth" tabindex="-1">Practice: feeling the fifth and fourth <a class="header-anchor" href="#practice-feeling-the-fifth-and-fourth" aria-label="Permalink to “Practice: feeling the fifth and fourth”">​</a></h2><p><strong>Exercise 1 — The fifth drone.</strong> 1) Choose a comfortable drone note. 2) Sing the perfect fifth above it. 3) Hold it and notice the feeling of stability — the &quot;lock&quot; of coinciding harmonics. 4) Try singing the fifth <em>below</em> the drone. 5) Notice how the quality changes while the relationship remains.</p><p><strong>Exercise 2 — The fourth&#39;s suspense.</strong> 1) With your drone, sing the perfect fourth above. 2) Notice how it differs from the fifth. 3) Does it feel like it wants to go somewhere? 4) Resolve it down to a major third. 5) Notice the sense of release — the sus4 resolving in your own voice.</p><p><strong>Exercise 3 — The inversion mirror.</strong> 1) Sing the fifth above your drone (e.g., drone C → sing G). 2) Now sing the fourth <em>below</em> the drone&#39;s octave (C an octave down → G is a fourth above it… equivalently, G is a fourth below the drone&#39;s upper octave). 3) Confirm it is the same pitch class: <strong>a fifth up = a fourth down from the octave</strong>. 4) Alternate the two voicings and feel the character flip from grounded to suspended while the color stays the same.</p><p><strong>In a jam:</strong></p><ul><li><strong>Fifths for power and stability:</strong> bass lines moving in fifths give strong direction; power chords are fifths; vocal harmonies in fifths sound open and supportive; counterpoint in fifths keeps lines independent but related.</li><li><strong>Fourths for suspension and interest:</strong> smooth voice leading, modern open quartal voicings, melodic ornament, modal interchange.</li><li><strong>Find your place:</strong> if the bass is walking fifths, complement with thirds or sixths; if the texture is crowded, open space with fourths; if the harmony is over-complex, ground it with a fifth.</li></ul><h2 id="chromatone-connection" tabindex="-1">Chromatone connection <a class="header-anchor" href="#chromatone-connection" aria-label="Permalink to “Chromatone connection”">​</a></h2><p>On the Chromatone spectrogram these intervals are consistent color geometries:</p><ul><li><strong>Perfect fifth</strong> — two colors at a specific, consistent spacing (7 steps of the 12-color wheel).</li><li><strong>Perfect fourth</strong> — the mirror spacing (5 steps), the fifth&#39;s complement within the octave cycle.</li></ul><p>With <strong>Chromatone stickers</strong> on your instrument, fifths and fourths form predictable visual patterns, and the circle of fifths becomes a color cycle you can see wrapping around your fretboard or keyboard — the architecture of harmony, rendered as geometry.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><ul><li><strong>Perfect fifth (3:2, ≈702¢ / 700¢ in 12-TET)</strong> — the most consonant non-octave interval; harmonics align at 3f = 2 × 1.5f; the generator of all 12 pitch classes via the circle of fifths.</li><li><strong>Pythagorean comma (≈23.46¢)</strong> — the gap between 12 fifths and 7 octaves; the birthmark of temperament (meantone, wolf fifth, and finally 12-TET&#39;s ¹²√2).</li><li><strong>Perfect fourth (4:3, ≈498¢ / 500¢)</strong> — the fifth&#39;s exact inversion (ratios multiply to 2:1, cents add to 1200); sensory consonance with a contextual, &quot;suspended&quot; life above the bass (sus4).</li><li><strong>The epogdoon (9:8, ≈204¢)</strong> — the whole tone, discovered as the space between fourth and fifth.</li><li><strong>On the 16-grid:</strong> P5 is an exact substrate line (24/16, +2.0¢); P4 floats between lines (21/16, −29.2¢) — physics mirroring phenomenology.</li><li><strong>Quartal/quintal harmony</strong> — fourths and fifths as building material: Persichetti&#39;s rootless ambiguity, the &quot;So What&quot; chord, and the tuning of guitars (fourths) vs. violins (fifths).</li><li><strong>Circle of fifths</strong> — Diletsky 1679; the map of keys, cadences, transposition, and modulation; a color cycle in Chromatone.</li><li><strong>Cognition &amp; culture</strong> — infants prefer consonant fifths from the first months of life, while cultural exposure tunes the preference; sa–pa drones, African pentatonics, and maqam shading all live inside the same 3:2 frame.</li><li><strong>Practice</strong> — feel the fifth&#39;s lock, the fourth&#39;s lean, and their inversion mirror; in a jam, choose fifths to ground and fourths to open space.</li></ul><p>Mastering fifths and fourths gives you the tools to understand and create harmonic structure — you are navigating the architecture of music itself. Next: the interval sitting exactly between them, the tritone.</p><h3 id="sources-further-reading" tabindex="-1">Sources &amp; further reading <a class="header-anchor" href="#sources-further-reading" aria-label="Permalink to “Sources &amp; further reading”">​</a></h3><ul><li>Plomp &amp; Levelt (1965), <em>Tonal consonance and critical bandwidth</em></li><li>Schellenberg &amp; Trehub (1996), <em>Natural musical intervals: evidence from infant listeners</em></li><li>Zentner &amp; Kagan (1996); Trainor &amp; Heinmiller (1998), infant consonance preference</li><li>Trainor (1997), ratio effects in infants and adults</li><li>McDermott et al. (2016), <em>Indifference to dissonance in native Amazonians</em></li><li>Diletsky (1679), <em>Idea grammatiki musikiyskoy</em>; Heinichen (1728)</li><li>Persichetti, <em>Twentieth Century Harmony</em></li><li>Chromatone course unit <em>vmt/intervals/fifth-fourth</em>.</li></ul>`,44)])}var m=i(f,[[`render`,p]]);export{d as __pageData,m as default};